#!/usr/bin/env node
/**
 * Vendors Microsoft's side-by-side ConPTY (`conpty.dll` + `OpenConsole.exe`)
 * into `src-tauri/conpty/`. Same rule as the icons: the files there are
 * generated by this script and never hand-edited — bump the pinned constants
 * below and re-run it.
 *
 * Why it exists: on Windows portable-pty falls back to the inbox ConPTY
 * (kernel32 -> system conhost), which drops OSC sequences it does not know, so
 * the OSC 133 command-block markers and OSC 7 cwd reports from the shell
 * integration never reach xterm.js. Since Windows Terminal 1.22 the
 * side-by-side ConPTY passes VT output through verbatim, and portable-pty
 * already prefers a `conpty.dll` found next to the executable.
 *
 * Source: the NuGet package `Microsoft.Windows.Console.ConPTY` (MIT,
 * (c) Microsoft Corporation). x64 only — the Windows build and the MSIX
 * manifest are both x64.
 *
 * Usage:
 *   node scripts/fetch-conpty.mjs            download, verify, extract
 *   node scripts/fetch-conpty.mjs --check    offline: verify the committed files
 *   node scripts/fetch-conpty.mjs --out DIR  extract somewhere else (testing)
 *
 * No dependencies: node stdlib only, with a minimal zip reader on node:zlib.
 */

import { createHash } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { inflateRawSync } from 'node:zlib';

const VERSION = '1.25.260930003';
const NUPKG_SHA256 = '02b07b349af66d801159bdf9e440d4a1ce78bb951f37fc8609731665afdae7ee';
const NUPKG_URL = `https://api.nuget.org/v3-flatcontainer/microsoft.windows.console.conpty/${VERSION}/microsoft.windows.console.conpty.${VERSION}.nupkg`;
const LICENSE_URL = 'https://raw.githubusercontent.com/microsoft/terminal/main/LICENSE';
const LICENSE_SHA256 = '5d177f23ecfeb0ea8e050b6a5a16355e1ae9a0b286436ca8f83ed08b3795be6b';

// Path inside the nupkg -> path under the output directory, and the hash of the
// extracted bytes.
const FILES = [
  {
    entry: 'runtimes/win-x64/native/conpty.dll',
    out: 'x64/conpty.dll',
    sha256: 'feeef341d891643c62d30b6b07800bc70f0bc148f44cb8c3bee84aa557ae805a',
  },
  {
    entry: 'build/native/runtimes/x64/OpenConsole.exe',
    out: 'x64/OpenConsole.exe',
    sha256: '3d66b23d0a71bb8eed2b77edc8b9df9bf54ce6c8fb74c863a30e760997f80586',
  },
];

const README = `# Bundled ConPTY

\`conpty.dll\` and \`OpenConsole.exe\` (x64) are Microsoft's side-by-side
ConPTY, taken unmodified from the NuGet package
\`Microsoft.Windows.Console.ConPTY\` ${VERSION}
(https://www.nuget.org/packages/Microsoft.Windows.Console.ConPTY/${VERSION}),
MIT licensed, (c) Microsoft Corporation — see \`LICENSE\`.

Senju Term ships them next to \`senju-term.exe\` (Windows only) so that OSC 7 and
OSC 133 sequences survive the pseudo console; the inbox ConPTY drops them.

These files are generated. Do not edit or replace them by hand: change the
pinned version and hashes in \`apps/desktop-app/scripts/fetch-conpty.mjs\` and
re-run it. \`node scripts/fetch-conpty.mjs --check\` verifies them offline.
`;

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');

const argv = process.argv.slice(2);
const checkOnly = argv.includes('--check');
const outIdx = argv.indexOf('--out');
const outDir = outIdx >= 0 ? resolve(argv[outIdx + 1]) : join(root, 'src-tauri', 'conpty');

/** Every file this script owns, as [relative path, expected sha256 | null]. */
function expectedFiles() {
  return [
    ...FILES.map((f) => [f.out, f.sha256]),
    ['LICENSE', LICENSE_SHA256],
    ['README.md', sha256(README)],
  ];
}

function check(dir) {
  const problems = [];
  for (const [rel, want] of expectedFiles()) {
    const p = join(dir, rel);
    if (!existsSync(p)) {
      problems.push(`${rel}: missing`);
      continue;
    }
    const got = sha256(readFileSync(p));
    if (got !== want) problems.push(`${rel}: sha256 ${got}, expected ${want}`);
  }
  return problems;
}

/**
 * Download helper. Node's fetch ignores HTTPS_PROXY on older releases, so if it
 * fails (or is unavailable) we retry through `curl`, which honours the proxy
 * and CA environment on every platform CI and dev boxes use.
 */
async function download(url) {
  try {
    const res = await fetch(url);
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    return Buffer.from(await res.arrayBuffer());
  } catch (err) {
    console.error(`fetch failed (${err.cause?.code ?? err.message}); retrying with curl`);
    return execFileSync('curl', ['-fsSL', '--retry', '3', url], {
      maxBuffer: 256 * 1024 * 1024,
    });
  }
}

/** Minimal zip reader: central directory -> { name: Buffer }, stored/deflate only. */
function readZip(buf, wanted) {
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 22 - 0xffff); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error('zip: end-of-central-directory not found');
  const count = buf.readUInt16LE(eocd + 10);
  let p = buf.readUInt32LE(eocd + 16);
  const found = {};
  for (let n = 0; n < count; n++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) throw new Error('zip: bad central directory entry');
    const method = buf.readUInt16LE(p + 10);
    const csize = buf.readUInt32LE(p + 20);
    const usize = buf.readUInt32LE(p + 24);
    const nameLen = buf.readUInt16LE(p + 28);
    const extraLen = buf.readUInt16LE(p + 30);
    const commentLen = buf.readUInt16LE(p + 32);
    const localOff = buf.readUInt32LE(p + 42);
    const name = buf.toString('utf8', p + 46, p + 46 + nameLen);
    p += 46 + nameLen + extraLen + commentLen;
    if (!wanted.includes(name)) continue;
    if (buf.readUInt32LE(localOff) !== 0x04034b50) throw new Error(`zip: bad local header for ${name}`);
    const dataStart = localOff + 30 + buf.readUInt16LE(localOff + 26) + buf.readUInt16LE(localOff + 28);
    const raw = buf.subarray(dataStart, dataStart + csize);
    const data = method === 0 ? raw : method === 8 ? inflateRawSync(raw) : null;
    if (!data) throw new Error(`zip: unsupported compression method ${method} for ${name}`);
    if (data.length !== usize) throw new Error(`zip: size mismatch for ${name}`);
    found[name] = data;
  }
  for (const name of wanted) if (!found[name]) throw new Error(`zip: ${name} not in the package`);
  return found;
}

function write(dir, rel, data) {
  const p = join(dir, rel);
  mkdirSync(dirname(p), { recursive: true });
  writeFileSync(p, data);
}

async function generate(dir) {
  const nupkg = await download(NUPKG_URL);
  const gotPkg = sha256(nupkg);
  if (gotPkg !== NUPKG_SHA256) {
    throw new Error(`nupkg sha256 ${gotPkg}, expected ${NUPKG_SHA256}`);
  }
  const entries = readZip(nupkg, FILES.map((f) => f.entry));
  const license = await download(LICENSE_URL);
  const gotLicense = sha256(license);
  if (gotLicense !== LICENSE_SHA256) {
    throw new Error(`LICENSE sha256 ${gotLicense}, expected ${LICENSE_SHA256} (upstream text changed — review it, then update LICENSE_SHA256)`);
  }
  for (const f of FILES) {
    const got = sha256(entries[f.entry]);
    if (got !== f.sha256) throw new Error(`${f.entry}: sha256 ${got}, expected ${f.sha256}`);
    write(dir, f.out, entries[f.entry]);
  }
  write(dir, 'LICENSE', license);
  write(dir, 'README.md', README);
}

if (checkOnly) {
  const problems = check(outDir);
  if (problems.length) {
    console.error(`conpty check: ${problems.length} problem(s) in ${outDir}`);
    for (const p of problems) console.error(`  - ${p}`);
    console.error('re-run: node scripts/fetch-conpty.mjs');
    process.exit(1);
  }
  console.log(`conpty check: OK (Microsoft.Windows.Console.ConPTY ${VERSION})`);
} else {
  try {
    await generate(outDir);
  } catch (err) {
    console.error(`fetch-conpty: ${err.message}`);
    process.exit(1);
  }
  const problems = check(outDir);
  if (problems.length) {
    console.error(problems.join('\n'));
    process.exit(1);
  }
  console.log(`wrote ${outDir} (Microsoft.Windows.Console.ConPTY ${VERSION})`);
}
